-- Retrodate dim_red_electrica: el generador excluye fecha_inicio (tiene DEFAULT NOW()),
-- pero los eventos arrancan en 2025-01-01 y el SP necesita SCD Tipo 2 funcional.
UPDATE dim_red_electrica
SET fecha_inicio = '2024-01-01 00:00:00+00'::TIMESTAMPTZ
WHERE fecha_inicio > '2025-01-01 00:00:00+00'::TIMESTAMPTZ;

-- Reasignar geografia a los medidores (el seed inserta sin sk_geografia_urbana)
WITH geo AS (
    SELECT sk_geografia_urbana AS sk,
           ROW_NUMBER() OVER (ORDER BY sk_geografia_urbana) AS rn
    FROM dim_geografia_urbana
)
UPDATE dim_red_electrica dre
SET sk_geografia_urbana = geo.sk
FROM geo
WHERE geo.rn = CASE
        WHEN dre.subestacion LIKE '%A%' THEN 1 + (dre.id_medidor % 4)
        WHEN dre.subestacion LIKE '%B%' THEN 5 + (dre.id_medidor % 4)
        WHEN dre.subestacion LIKE '%C%' THEN 1 + (dre.id_medidor % 8)
        ELSE 1 + (dre.id_medidor % 8)
    END;

